impl TransportUnicastUniversal {
    fn trigger_callback(
        &self,
        callback: &dyn TransportPeerEventHandler,
        #[allow(unused_mut)] // shared-memory feature requires mut
        mut msg: NetworkMessageMut,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        #[cfg(feature = "stats")]
        stats.inc_network_message(
            zenoh_stats::Rx,
            zenoh_protocol::network::NetworkMessageExt::as_ref(&msg),
        );
        #[cfg(feature = "shared-memory")]
        if let Some(shm_context) = &self.shm_context {
            if let Err(e) = crate::common::shm::interop::map_zmsg_to_shmbuf(
                msg.as_mut(),
                &shm_context.shm_reader,
                &link.shm,
            ) {
                tracing::debug!("Error receiving SHM buffer: {e}");
                return Ok(());
            }
        }

        callback.handle_message(msg)
    }

    fn handle_close(&self, link: &Link, _reason: u8, session: bool) -> ZResult<()> {
        // Delete and clean up
        let c_transport = self.clone();
        let c_link = link.clone();
        // Spawn a task to avoid a deadlock waiting for this same task
        // to finish in the link close() joining the rx handle
        zenoh_runtime::ZRuntime::Net.spawn(async move {
            if session {
                let _ = c_transport.delete().await;
            } else {
                let _ = c_transport.del_link(c_link).await;
            }
        });

        Ok(())
    }

    fn handle_frame<R: BacktrackableReader>(
        &self,
        frame: FrameReader<R>,
        batch_len: usize,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        let priority = frame.ext_qos.priority();
        let c = if self.is_qos() {
            &self.priority_rx[priority as usize]
        } else if priority == Priority::DEFAULT {
            &self.priority_rx[0]
        } else {
            bail!(
                "Transport: {}. Unknown priority: {:?}.",
                self.config.zid,
                priority
            );
        };

        let mut guard = match frame.reliability {
            Reliability::Reliable => zlock!(c.reliable),
            Reliability::BestEffort => zlock!(c.best_effort),
        };

        let position = match guard.hold.as_ref() {
            None => None,
            Some(hold) => Some(hold.position(&guard.sn, frame.sn)?),
        };
        match position {
            None => {
                if !self.verify_sn("Frame", frame.sn, &mut guard)? {
                    // Drop invalid message and continue
                    return Ok(());
                }
                self.deliver_frame(
                    frame,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )
            }
            // A bound of the hold was passed: the transport is closing
            Some(_) if guard.bounded => Ok(()),
            Some(Position::Next) => {
                guard.sn.set(frame.sn)?;
                self.deliver_frame(
                    frame,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?;
                self.release_held(
                    &mut guard,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )
            }
            Some(Position::Ahead) => {
                // A held frame keeps its batch's buffer alive, so it counts at the batch's length
                let sn = frame.sn;
                let messages = frame.collect();
                self.keep_held(&mut guard, priority, sn, Held::Frame(messages), batch_len);
                Ok(())
            }
            Some(Position::Old) => {
                tracing::trace!(
                    "Transport: {}. Frame with old SN dropped: {}. Last delivered: {}.",
                    self.config.zid,
                    frame.sn,
                    guard.sn.get()
                );
                Ok(())
            }
        }
    }

    fn deliver_frame(
        &self,
        messages: impl IntoIterator<Item = NetworkMessage>,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        if let Some(callback) = self.callback.get() {
            for mut msg in messages {
                self.trigger_callback(
                    callback.as_ref(),
                    msg.as_mut(),
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?;
            }
        } else {
            tracing::debug!(
                "Transport: {}. No callback available, dropping messages",
                self.config.zid,
            );
        }

        Ok(())
    }

    fn handle_fragment(
        &self,
        fragment: Fragment,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        let priority = fragment.ext_qos.priority();
        let c = if self.is_qos() {
            &self.priority_rx[priority as usize]
        } else if priority == Priority::DEFAULT {
            &self.priority_rx[0]
        } else {
            bail!(
                "Transport: {}. Unknown priority: {:?}.",
                self.config.zid,
                priority
            );
        };

        let mut guard = match fragment.reliability {
            Reliability::Reliable => zlock!(c.reliable),
            Reliability::BestEffort => zlock!(c.best_effort),
        };

        let position = match guard.hold.as_ref() {
            None => None,
            Some(hold) => Some(hold.position(&guard.sn, fragment.sn)?),
        };
        match position {
            None => {
                if !self.verify_sn("Fragment", fragment.sn, &mut guard)? {
                    // Drop invalid message and continue
                    return Ok(());
                }
                self.deliver_fragment(
                    &mut guard.defrag,
                    fragment,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )
            }
            // A bound of the hold was passed: the transport is closing
            Some(_) if guard.bounded => Ok(()),
            Some(Position::Next) => {
                guard.sn.set(fragment.sn)?;
                self.deliver_fragment(
                    &mut guard.defrag,
                    fragment,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?;
                self.release_held(
                    &mut guard,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )
            }
            Some(Position::Ahead) => {
                let (sn, size) = (fragment.sn, fragment.payload.len());
                self.keep_held(&mut guard, priority, sn, Held::Fragment(fragment), size);
                Ok(())
            }
            Some(Position::Old) => {
                tracing::trace!(
                    "Transport: {}. Fragment with old SN dropped: {}. Last delivered: {}.",
                    self.config.zid,
                    fragment.sn,
                    guard.sn.get()
                );
                Ok(())
            }
        }
    }

    fn deliver_fragment(
        &self,
        defrag: &mut DefragBuffer,
        fragment: Fragment,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        let Fragment {
            more,
            sn,
            ext_first,
            ext_drop,
            payload,
            ..
        } = fragment;

        if self.config.patch.has_fragmentation_markers() {
            if ext_first.is_some() {
                defrag.clear();
            } else if defrag.is_empty() {
                tracing::trace!(
                    "Transport: {}. First fragment received without start marker.",
                    self.manager.config.zid,
                );
                return Ok(());
            }
            if ext_drop.is_some() {
                defrag.clear();
                return Ok(());
            }
        }
        if defrag.is_empty() {
            let _ = defrag.sync(sn);
        }
        if let Err(e) = defrag.push(sn, payload) {
            // Defrag errors don't close transport
            tracing::trace!("{}", e);
            return Ok(());
        }
        if !more {
            // When shared-memory feature is disabled, msg does not need to be mutable
            if let Some(mut msg) = defrag.defragment() {
                if let Some(callback) = self.callback.get() {
                    return self.trigger_callback(
                        callback.as_ref(),
                        msg.as_mut(),
                        #[cfg(feature = "stats")]
                        stats,
                        #[cfg(feature = "shared-memory")]
                        link,
                    );
                } else {
                    tracing::debug!(
                        "Transport: {}. No callback available, dropping messages: {:?}",
                        self.config.zid,
                        msg
                    );
                }
            } else {
                tracing::trace!("Transport: {}. Defragmentation error.", self.config.zid);
            }
        }

        Ok(())
    }

    /// Delivers, in number order, every held item that the last delivery unblocked.
    fn release_held(
        &self,
        guard: &mut MutexGuard<'_, TransportChannelRx>,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
        #[cfg(feature = "shared-memory")] link: &TransportLinkUnicastRx,
    ) -> ZResult<()> {
        let channel = &mut **guard;
        while let Some(held) = channel
            .hold
            .as_mut()
            .and_then(|hold| hold.next_ready(&mut channel.sn))
        {
            match held {
                Held::Frame(messages) => self.deliver_frame(
                    messages,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?,
                Held::Fragment(fragment) => self.deliver_fragment(
                    &mut channel.defrag,
                    fragment,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?,
            }
        }

        Ok(())
    }

    /// Holds an item that arrived ahead of a gap, watching the gap's age from its first item,
    /// and closes the transport if holding it would pass the size bound.
    fn keep_held(
        &self,
        guard: &mut MutexGuard<'_, TransportChannelRx>,
        priority: Priority,
        sn: TransportSn,
        held: Held,
        size: usize,
    ) {
        let Some(hold) = guard.hold.as_mut() else {
            return;
        };
        let first = hold.since().is_none();
        match hold.keep(sn, held, size, Instant::now()) {
            Ok(()) => {
                if first {
                    self.watch_hold(priority);
                }
            }
            Err(Overflow) => {
                let held_size = hold.held_size();
                guard.bounded = true;
                tracing::warn!(
                    "Transport: {}. Priority {:?}: holding {} more bytes on top of the {} held would pass the bound of {} bytes; closing the transport",
                    self.config.zid,
                    priority,
                    size,
                    held_size,
                    self.manager.config.unicast.ordering.max_held_size,
                );
                self.close_for_bound();
            }
        }
    }

    /// After `max_hold`, closes the transport if `priority`'s gap is still at least that old.
    fn watch_hold(&self, priority: Priority) {
        enum Watch {
            Filled,
            Later(Instant),
            Passed(Duration),
        }

        let max_hold = self.manager.config.unicast.ordering.max_hold;
        let index = if self.is_qos() { priority as usize } else { 0 };
        let transport = self.clone();
        zenoh_runtime::ZRuntime::Net.spawn(async move {
            let mut deadline = tokio::time::Instant::now() + max_hold;
            loop {
                tokio::time::sleep_until(deadline).await;
                if transport.callback.get().is_none() {
                    // The transport closed meanwhile
                    return;
                }
                let watch = {
                    let mut guard = zlock!(transport.priority_rx[index].reliable);
                    match guard.hold.as_ref().and_then(|hold| hold.since()) {
                        None => Watch::Filled,
                        Some(since) if since.elapsed() < max_hold => Watch::Later(since + max_hold),
                        Some(_) if guard.bounded => Watch::Filled,
                        Some(since) => {
                            guard.bounded = true;
                            Watch::Passed(since.elapsed())
                        }
                    }
                };
                match watch {
                    Watch::Filled => return,
                    // The gap filled and a later one opened: it is timed from its own oldest item
                    Watch::Later(at) => deadline = tokio::time::Instant::from_std(at),
                    Watch::Passed(age) => {
                        tracing::warn!(
                            "Transport: {}. Priority {:?}: a gap held for {:?} passed the bound of {:?}; closing the transport",
                            transport.config.zid,
                            priority,
                            age,
                            max_hold,
                        );
                        transport.close_for_bound();
                        return;
                    }
                }
            }
        });
    }

    /// Closes the transport from a task of its own, since the read path must not join its own
    /// task (see `handle_close`).
    fn close_for_bound(&self) {
        let transport = self.clone();
        zenoh_runtime::ZRuntime::Net.spawn(async move {
            let _ = TransportUnicastTrait::close(&transport, close::reason::GENERIC).await;
        });
    }

    fn verify_sn(
        &self,
        message_type: &str,
        sn: TransportSn,
        guard: &mut MutexGuard<'_, TransportChannelRx>,
    ) -> ZResult<bool> {
        let precedes = guard.sn.roll(sn)?;
        if !precedes {
            tracing::trace!(
                "Transport: {}. {} with invalid SN dropped: {}. Expected: {}.",
                self.config.zid,
                message_type,
                sn,
                guard.sn.next()
            );
            return Ok(false);
        }

        Ok(true)
    }

    pub(super) fn read_messages<TBuffer: BacktrackableReader + Buffer + Debug>(
        &self,
        mut batch: RBatch<TBuffer>,
        link: &TransportLinkUnicastRx,
        #[cfg(feature = "stats")] stats: &zenoh_stats::LinkStats,
    ) -> ZResult<()> {
        let batch_len = batch.len();
        while !batch.is_empty() {
            if let Ok(frame) = batch.decode() {
                tracing::trace!("Received: {:?}", frame);
                #[cfg(feature = "stats")]
                {
                    stats.inc_transport_message(zenoh_stats::Rx, 1);
                }
                self.handle_frame(
                    frame,
                    batch_len,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?;
                continue;
            }
            let msg: TransportMessage = batch
                .decode()
                .map_err(|_| zerror!("{}: decoding error", link.link))?;

            tracing::trace!("Received: {:?}", msg);

            #[cfg(feature = "stats")]
            {
                stats.inc_transport_message(zenoh_stats::Rx, 1);
            }

            match msg.body {
                TransportBody::Frame(_) => unreachable!(),
                TransportBody::Fragment(fragment) => self.handle_fragment(
                    fragment,
                    #[cfg(feature = "stats")]
                    stats,
                    #[cfg(feature = "shared-memory")]
                    link,
                )?,
                TransportBody::Close(Close { reason, session }) => {
                    let l = Link::new_unicast(
                        &link.link,
                        link.config.priorities.clone(),
                        link.config.reliability,
                    );
                    self.handle_close(&l, reason, session)?
                }
                TransportBody::KeepAlive(KeepAlive { .. }) => {}
                _ => {
                    tracing::debug!(
                        "Transport: {}. Message handling not implemented: {:?}",
                        self.config.zid,
                        msg
                    );
                }
            }
        }

        // Process the received message

        Ok(())
    }
}
